    _setState: function (state) {
        this._state = Ext.apply(this._getState(), state);
        sessionStorage.setItem('cms-state', JSON.stringify(this._state));
    },

    _getState: function () {
        return JSON.parse(sessionStorage.getItem('cms-state'));
    },

    constructor: function (cfg) {
        cfg = core.nullValue(cfg, {});

        this.state = JSON.parse(sessionStorage.getItem('cms-state'));

        Ext.apply(cfg, {
            disableSaveAndNew: true,
            callback: {
                success: {
                    scope: this,
                    fn: function (instance) {
                        if (this.action == 'update') {
                            this.destroy();
                            this._setState({ post: null });
                            this.ownerGrid.getStore().reload();
                        } else {
                            this.getFormPanel().getForm().findField('categories').objectId(instance.pk);
                            this.getFormPanel().getForm().findField('files').objectId(instance.pk);
                            this.oId = instance.pk;
                            this._setState({ post: instance.pk });
                            this.action = 'update';
                        }
                    },
                },
            },
            saveAndContinue: {
                scope: this,
                fn: function (instance) {},
            },
        });

        web.cms.post.Window.superclass.constructor.call(this, cfg);

        if (this.action != 'create') this._setState({ post: cfg.values.pk });
    },
